41	const actionDir = join(import.meta.dirname, "..");
42	const repoRoot = join(actionDir, "..", "..", "..");
43	const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
44	
45	const readSkill = (name: string): Promise<string> =>
46	  readFile(join(skillsDir, name, "SKILL.md"), "utf8");
47	
48	const [linearPlan, linearRun, plan, run, runPrimed, pipeline] = await Promise.all([
49	  readSkill("linear-plan"),
50	  readSkill("linear-run"),
51	  readSkill("plan"),
52	  readSkill("run"),
53	  readSkill("run-primed"),
54	  readFile(join(skillsDir, "plan/references/pipeline.md"), "utf8"),
55	]);
