57	/** Every verdict `linear-run`'s validation table must name, fallback ones first. */
58	const fallbackVerdicts = ["missing", "version-mismatch", "malformed", "unverifiable"];
59	const allVerdicts = [...fallbackVerdicts, "valid"];
60	
61	/**
62	 * `### <name>` rows of the stored-plan template in `linear-plan`, split by its own
63	 * required/caller-owned marker. Reading the producer's template is what makes a renamed
64	 * section fail here rather than at runtime against a live ticket.
65	 */
66	function storedSections(source: string, kind: "required" | "caller-owned"): string[] {
67	  const rows = source.matchAll(/^###\s+(.+?)\s+<-\s+(required|caller-owned)$/gm);
68	  return [...rows].filter((row) => row[2] === kind).map((row) => row[1].trim());
69	}
