85	 * description moves into. Pinned so the cut around preserved user text stays a fixed
86	 * emission form, mirroring the `+++ Original prompt +++` preamble in `linear-create`.
87	 */
88	const originalTaskWrapper = linearPlan.match(/```text\n(\+\+\+ Original task\n.*?)```/s)?.[1] ?? "";
