91	function sectionTableRow(source: string, key: string): string {
92	  const row = source
93	    .split("\n")
94	    .map((line) => line.split("|").map((cell) => cell.trim()))
95	    .find((cells) => cells.length > 2 && cells[1] === key);
96	  return row ? row[2] : "";
97	}
